"use client";

import { useEffect, useState } from "react";
import styles from "./CinematicHero.module.css";

const sequence = [
  "Your brand could be doing more.",
  "More attention.",
  "More impact.",
  "More connection.",
  "More growth.",
  "Websites that represent your brand.",
  "Web apps that move your business forward.",
  "Mobile apps that keep your customers connected.",
  "Branding that makes you impossible to ignore.",
  "We discuss. We design. We build.",
  "Everything your brand needs to grow.",
];

export default function CinematicHero() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showCTA, setShowCTA] = useState(false);
  const [isEntered, setIsEntered] = useState(false);
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    // Only lock scrolling if we haven't entered yet
    if (!isEntered && !isExiting) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }

    return () => {
      document.body.style.overflow = "";
    };
  }, [isEntered, isExiting]);

  useEffect(() => {
    if (currentIndex < sequence.length - 1) {
      const timer = setTimeout(() => {
        setCurrentIndex((prev) => prev + 1);
      }, 3500); // 3.5s per line
      return () => clearTimeout(timer);
    } else {
      const ctaTimer = setTimeout(() => {
        setShowCTA(true);
      }, 1000); // Wait 1s after last text appears to show CTA
      return () => clearTimeout(ctaTimer);
    }
  }, [currentIndex]);

  const handleEnter = () => {
    setIsExiting(true);
    setTimeout(() => {
      setIsEntered(true);
    }, 1000); // Wait for exit animation to complete
  };

  if (isEntered) return null;

  return (
    <section className={`${styles.heroRoot} ${isExiting ? styles.exiting : ""}`}>
      <div className={styles.heroContent}>
        {sequence.map((text, idx) => (
          <h1
            key={idx}
            className={`${styles.heroText} ${
              idx === currentIndex ? styles.active : ""
            } ${idx < currentIndex ? styles.previous : ""}`}
            aria-hidden={idx !== currentIndex}
          >
            {text}
          </h1>
        ))}
        
        <div className={`${styles.ctaWrapper} ${showCTA ? styles.ctaProminent : ""}`}>
          <button onClick={handleEnter} className={styles.circularCta} aria-label="Start Our Branding Story">
            <div className={styles.circularTextWrapper}>
              <svg viewBox="0 0 100 100" width="100%" height="100%">
                <defs>
                  <path
                    id="circlePath"
                    d="M 50, 50 m -40, 0 a 40,40 0 1,1 80,0 a 40,40 0 1,1 -80,0"
                  />
                </defs>
                <text className={styles.circularText}>
                  <textPath href="#circlePath" startOffset="0%">
                    START OUR BRANDING STORY • START OUR BRANDING STORY • 
                  </textPath>
                </text>
              </svg>
            </div>
            <span className={styles.centerArrow}>&rarr;</span>
          </button>
        </div>
      </div>
    </section>
  );
}
